using TwistTidy.Core.Models;
using TwistTidy.Core.Services;

string root=Path.GetFullPath(Path.Combine(".test-data",DateTime.Now.ToString("yyyyMMdd-HHmmss")));
Directory.CreateDirectory(root);int passed=0,failed=0;
void Test(string name,Action test){try{test();Console.WriteLine("PASS "+name);passed++;}catch(Exception e){Console.WriteLine("FAIL "+name+": "+e);failed++;}}
void Assert(bool condition,string message="Assertion failed"){if(!condition)throw new Exception(message);}
void Throws(Action action){bool threw=false;try{action();}catch(IOException){threw=true;}Assert(threw,"Expected a safety refusal");}
string Folder(string name){string dir=Path.Combine(root,name);Directory.CreateDirectory(dir);return dir;}
string FileAt(string folder,string name,string content="test content"){string p=Path.Combine(folder,name);File.WriteAllText(p,content);return p;}
PlanRow Move(string source,string target){var f=new FileInfo(source);return new(){Source=source,Destination=target,Size=f.Length,ModifiedTicks=f.LastWriteTimeUtc.Ticks};}
(LocalStore Store,ExecutionService Engine) Engine(string name){var s=new LocalStore(Folder("history-"+name));return(s,new(s));}
Test("system folder blocked",()=>Throws(()=>Safety.Check(Environment.GetFolderPath(Environment.SpecialFolder.Windows))));
Test("program files blocked",()=>Throws(()=>Safety.Check(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles),"test"))));
Test("whole drive blocked",()=>Throws(()=>Safety.Check(Path.GetPathRoot(root)!)));
Test("path traversal rejected",()=>Throws(()=>Safety.Relative("Footage/../../Windows")));
Test("absolute template rejected",()=>Throws(()=>Safety.Relative(@"C:\unsafe")));
Test("empty template segment rejected",()=>Throws(()=>Safety.Relative("one//two")));
Test("reserved device name normalized",()=>Assert(Safety.Segment("CON")=="_CON"));
Test("unique suffix reserves plan paths",()=>{var d=Folder("clash");var a=FileAt(d,"same.mov");var set=new HashSet<string>(StringComparer.OrdinalIgnoreCase);Assert(Safety.Unique(a,set).EndsWith("same (2).mov"));Assert(Safety.Unique(a,set).EndsWith("same (3).mov"));});
Test("scan exclusions and recursion",()=>{var d=Folder("scan");FileAt(d,"a.txt");Directory.CreateDirectory(Path.Combine(d,"skip"));FileAt(Path.Combine(d,"skip"),"hidden.txt");Directory.CreateDirectory(Path.Combine(d,"sub"));FileAt(Path.Combine(d,"sub"),"b.txt");Assert(new Scanner().Scan(d,["skip"],default).Count==2);});
Test("scan cancellation",()=>{using var c=new CancellationTokenSource();c.Cancel();bool cancelled=false;try{new Scanner().Scan(root,[],c.Token);}catch(OperationCanceledException){cancelled=true;}Assert(cancelled);});
Test("sort planning never moves originals",()=>{string src=Folder("sort"),dest=Folder("sort-dest");var p=FileAt(src,"DJI_0001.mp4");var f=new Scanner().Scan(src,[],default);var rows=Planner.Sort(f,dest,"{type}/{source}/{date}",new(),default);Assert(rows.Count==1);Assert(rows[0].Destination.Contains(Path.Combine("Footage","Drone")));Assert(rows[0].Note.Contains("modified date"));Assert(File.Exists(p));Assert(!File.Exists(rows[0].Destination));});
Test("sort skips unknown file extensions",()=>{var d=Folder("unknown");FileAt(d,"file.exe");Assert(Planner.Sort(new Scanner().Scan(d,[],default),Folder("unknown-dest"),"{type}",new(),default).Count==0);});
Test("project folder preview and nesting",()=>{var parent=Folder("project");var rows=Planner.Project(parent,"Client","Film",new DateTime(2026,10,26),"Documentary",new(){Folders=["Footage/A","Exports"]},true);Assert(rows.Count==4);Assert(!Directory.Exists(rows[0].Destination));Assert(rows.Any(r=>r.Destination.EndsWith(Path.Combine("Footage","A"))));});
Test("move and durable undo round trip",()=>{var d=Folder("move");var source=FileAt(d,"a.txt");var target=Path.Combine(d,"new","a.txt");var (s,e)=Engine("move");var b=e.Execute("test",[Move(source,target)],default);Assert(!File.Exists(source)&&File.Exists(target));var reloaded=s.History().Single();e.Undo(reloaded,e.UndoPreview(reloaded),default);Assert(File.Exists(source)&&!File.Exists(target));Assert(!Directory.Exists(Path.GetDirectoryName(target)));Assert(reloaded.State=="Undone");});
Test("unchecked preview row does not execute",()=>{var d=Folder("unchecked");var source=FileAt(d,"a.txt");var target=Path.Combine(d,"b.txt");var row=Move(source,target);row.Selected=false;var (_,e)=Engine("unchecked");Throws(()=>e.Execute("test",[row],default));Assert(File.Exists(source)&&!File.Exists(target));});
Test("source changed after preview is skipped",()=>{var d=Folder("changed");var p=FileAt(d,"a.txt");var row=Move(p,Path.Combine(d,"b.txt"));File.AppendAllText(p,"edited");var (_,e)=Engine("changed");var b=e.Execute("test",[row],default);Assert(File.Exists(p)&&!File.Exists(row.Destination));Assert(b.State=="Completed with issues");});
Test("destination appeared after preview is protected",()=>{var d=Folder("newtarget");var p=FileAt(d,"a.txt");var row=Move(p,Path.Combine(d,"b.txt"));File.WriteAllText(row.Destination,"existing");var (_,e)=Engine("newtarget");e.Execute("test",[row],default);Assert(File.ReadAllText(row.Destination)=="existing"&&File.Exists(p));});
Test("undo does not overwrite restored source",()=>{var d=Folder("undoclash");var p=FileAt(d,"a.txt","original");var target=Path.Combine(d,"b.txt");var (_,e)=Engine("undoclash");var b=e.Execute("test",[Move(p,target)],default);File.WriteAllText(p,"new content");var undo=e.UndoPreview(b);Assert(undo.First().Destination.EndsWith("a (2).txt"));e.Undo(b,undo,default);Assert(File.ReadAllText(p)=="new content");Assert(File.ReadAllText(Path.Combine(d,"a (2).txt"))=="original");});
Test("undo protects later edits",()=>{var d=Folder("undoedit");var p=FileAt(d,"a.txt");var target=Path.Combine(d,"b.txt");var (_,e)=Engine("undoedit");var b=e.Execute("test",[Move(p,target)],default);File.WriteAllText(target,"editor changes");e.Undo(b,e.UndoPreview(b),default);Assert(File.ReadAllText(target)=="editor changes"&&!File.Exists(p));Assert(b.State=="Partially undone");});
Test("undo refuses to remove nonempty project folders",()=>{var d=Folder("nonempty");var (_,e)=Engine("nonempty");var rows=Planner.Project(d,"A","B",DateTime.Today,"Video",new(){Folders=["Footage"]},false);var b=e.Execute("test",rows,default);FileAt(rows[1].Destination,"new.mov");e.Undo(b,e.UndoPreview(b),default);Assert(Directory.Exists(rows[1].Destination));Assert(b.State=="Partially undone");});
Test("duplicate content ignores names",()=>{var d=Folder("duplicates");FileAt(d,"one.txt","matching");FileAt(d,"two.bin","matching");FileAt(d,"other.txt","different");var rows=Planner.Duplicates(new Scanner().Scan(d,[],default),0,"",true,default,null,[]);Assert(rows.Count==2&&rows.Count(r=>r.Action=="Keep")==1);Assert(rows.Select(r=>r.Hash).Distinct().Count()==1);});
Test("duplicate extension filter",()=>{var d=Folder("duplicatefilter");FileAt(d,"a.mov","same");FileAt(d,"b.txt","same");Assert(Planner.Duplicates(new Scanner().Scan(d,[],default),0,"mov",true,default,null,[]).Count==0);});
Test("same-sized distinct contents are not duplicates",()=>{var d=Folder("samesize");FileAt(d,"a.txt","aaaa");FileAt(d,"b.txt","bbbb");Assert(Planner.Duplicates(new Scanner().Scan(d,[],default),0,"",true,default,null,[]).Count==0);});
Test("full hash catches a partial-hash collision",()=>{var d=Folder("partial");var a=new byte[1024*1024];var b=(byte[])a.Clone();b[90000]=42;string p=Path.Combine(d,"a.bin"),q=Path.Combine(d,"b.bin");File.WriteAllBytes(p,a);File.WriteAllBytes(q,b);Assert(Hashing.Partial(p,default)==Hashing.Partial(q,default));Assert(Planner.Duplicates(new Scanner().Scan(d,[],default),0,"",true,default,null,[]).Count==0);});
Test("minimum duplicate size filter",()=>{var d=Folder("minimum");FileAt(d,"a.txt");FileAt(d,"b.txt");Assert(Planner.Duplicates(new Scanner().Scan(d,[],default),1024,"",true,default,null,[]).Count==0);});
Test("duplicate keeper changed blocks actions",()=>{var d=Folder("keeper");FileAt(d,"a.txt");FileAt(d,"b.txt");var rows=Planner.Duplicates(new Scanner().Scan(d,[],default),0,"",true,default,null,[]);File.WriteAllText(rows.First(r=>r.Action=="Keep").Source,"changed keeper");var (_,e)=Engine("keeper");Throws(()=>e.Execute("duplicate",rows,default));Assert(Directory.GetFiles(d).Length==2);});
Test("locked file move fails safely",()=>{var d=Folder("locked");var p=FileAt(d,"a.txt");var row=Move(p,Path.Combine(d,"b.txt"));using var locked=new FileStream(p,FileMode.Open,FileAccess.ReadWrite,FileShare.None);var (_,e)=Engine("locked");var b=e.Execute("test",[row],default);Assert(File.Exists(p)&&!File.Exists(row.Destination));Assert(b.State=="Completed with issues");});
Test("execution cancellation leaves unstarted files",()=>{var d=Folder("cancel");var p=FileAt(d,"a.txt");var row=Move(p,Path.Combine(d,"b.txt"));var (_,e)=Engine("cancel");using var c=new CancellationTokenSource();c.Cancel();var b=e.Execute("test",[row],c.Token);Assert(File.Exists(p)&&b.State.StartsWith("Cancelled"));});
Test("pending move journal recovers after interruption",()=>{var d=Folder("pending");var p=FileAt(d,"a.txt");var q=Path.Combine(d,"b.txt");string hash=Hashing.Full(p);File.Move(p,q);var (s,e)=Engine("pending");var b=new Batch{Entries=[new(){Action="Move",Source=p,Destination=q,Hash=hash,State="Pending"}]};s.Save(b);var rows=e.UndoPreview(b);Assert(rows.Count==1);e.Undo(b,rows,default);Assert(File.Exists(p));});
Test("settings JSON persists custom rules",()=>{var (s,_)=Engine("settings");var settings=new Settings{Theme="Light"};settings.CameraPatterns.Add(new(){Prefix="CUSTOM",Source="Camera A"});s.SaveSettings(settings);Assert(s.LoadSettings().Theme=="Light"&&s.LoadSettings().CameraPatterns.Any(p=>p.Source=="Camera A"));});
Test("custom project name pattern",()=>{var rows=Planner.Project(Folder("namepattern"),"Client","Film",new(2026,10,26),"Drone",new(){Folders=["Media"]},false,"{client}_{project}_{type}_{date}");Assert(rows[0].Destination.EndsWith("Client_Film_Drone_2026-10-26"));});
Test("invalid project pattern rejected",()=>Throws(()=>Planner.Project(Folder("invalidpattern"),"A","B",DateTime.Today,"Video",new(),false,"../{project}")));
Test("malformed settings preserve data and load defaults",()=>{var (s,_)=Engine("badsettings");File.WriteAllText(Path.Combine(s.Root,"settings.json"),"broken json");Assert(s.LoadSettings().Theme=="Dark");Assert(s.Warnings.Count==1);Assert(File.ReadAllText(Path.Combine(s.Root,"settings.json"))=="broken json");});
Test("malformed history does not hide valid batches",()=>{var (s,_)=Engine("badhistory");s.Save(new(){Title="valid"});File.WriteAllText(Path.Combine(s.Root,"History","broken.json"),"broken");Assert(s.History().Count==1&&s.Warnings.Count==1);});
Test("interrupted undo detects already restored content",()=>{var d=Folder("undopending");var p=FileAt(d,"a.txt");string q=Path.Combine(d,"b.txt"),hash=Hashing.Full(p);var (s,e)=Engine("undopending");var b=new Batch{Entries=[new(){Action="Move",Source=p,Destination=q,Hash=hash,State="Undo pending",UndoDestination=p}]};s.Save(b);Assert(e.UndoPreview(b).Count==0);Assert(b.Entries[0].State=="Undone");});
Test("duplicate review move and undo preserve keeper",()=>{var d=Folder("reviewmove");FileAt(d,"a.txt");FileAt(d,"b.txt");var rows=Planner.Duplicates(new Scanner().Scan(d,[],default),0,"",true,default,null,[]);var dup=rows.Single(r=>r.Action!="Keep");dup.Action="Move";dup.Destination=Path.Combine(d,"Review",Path.GetFileName(dup.Source));var (_,e)=Engine("reviewmove");var b=e.Execute("duplicates",rows,default);Assert(File.Exists(rows.Single(r=>r.Action=="Keep").Source));Assert(File.Exists(dup.Destination));e.Undo(b,e.UndoPreview(b),default);Assert(File.Exists(dup.Source));});
if(args.Contains("--recycle"))
{
    Test("Windows Recycle Bin and restore round trip",()=>{var d=Folder("recycle");var p=FileAt(d,"recycle-test-"+Guid.NewGuid()+".txt","Recycle and restore test");var row=Move(p,"Recycle Bin");row.Action="Recycle";var (_,e)=Engine("recycle");var b=e.Execute("recycle test",[row],default);Assert(!File.Exists(p),string.Join(";",b.Entries.Select(x=>x.Error)));Assert(b.Entries.Single().RecycleData.Length>0);e.Undo(b,e.UndoPreview(b),default);Assert(File.ReadAllText(p)=="Recycle and restore test");Assert(b.State=="Undone");});
    Test("project README creation and full undo",()=>{var d=Folder("readme");var (_,e)=Engine("readme");var rows=Planner.Project(d,"Client","Film",DateTime.Today,"Video",new(){Folders=["A/B","Exports"]},true);var b=e.Execute("project",rows,default);Assert(File.Exists(rows.Last().Destination));e.Undo(b,e.UndoPreview(b),default);Assert(!Directory.Exists(rows.First().Destination));});
}
Console.WriteLine($"\n{passed} passed; {failed} failed. Fixtures retained at {root}");Environment.ExitCode=failed==0?0:1;

